USE hyperapex_business_hub;

CREATE TABLE IF NOT EXISTS quotations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, client_id BIGINT UNSIGNED NOT NULL, request_id BIGINT UNSIGNED NULL, quotation_number VARCHAR(50) NOT NULL UNIQUE, issue_date DATE NOT NULL, valid_until DATE NULL, status ENUM('DRAFT','SENT','ACCEPTED','DECLINED','EXPIRED','CANCELLED') NOT NULL DEFAULT 'DRAFT', notes TEXT, subtotal DECIMAL(15,2) NOT NULL DEFAULT 0, tax_rate DECIMAL(5,2) NOT NULL DEFAULT 0, tax_amount DECIMAL(15,2) NOT NULL DEFAULT 0, discount_amount DECIMAL(15,2) NOT NULL DEFAULT 0, total_amount DECIMAL(15,2) NOT NULL DEFAULT 0, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (client_id) REFERENCES clients(id), FOREIGN KEY (request_id) REFERENCES service_requests(id) ON DELETE SET NULL, FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS quotation_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, quotation_id BIGINT UNSIGNED NOT NULL, description VARCHAR(255) NOT NULL, quantity DECIMAL(12,2) NOT NULL DEFAULT 1, unit_price DECIMAL(15,2) NOT NULL DEFAULT 0, line_total DECIMAL(15,2) NOT NULL DEFAULT 0, FOREIGN KEY (quotation_id) REFERENCES quotations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, client_id BIGINT UNSIGNED NOT NULL, request_id BIGINT UNSIGNED NULL, quotation_id BIGINT UNSIGNED NULL, invoice_number VARCHAR(50) NOT NULL UNIQUE, issue_date DATE NOT NULL, due_date DATE NULL, status ENUM('DRAFT','ISSUED','PARTIALLY_PAID','PAID','OVERDUE','VOID') NOT NULL DEFAULT 'DRAFT', subtotal DECIMAL(15,2) NOT NULL DEFAULT 0, tax_rate DECIMAL(5,2) NOT NULL DEFAULT 0, tax_amount DECIMAL(15,2) NOT NULL DEFAULT 0, discount_amount DECIMAL(15,2) NOT NULL DEFAULT 0, total_amount DECIMAL(15,2) NOT NULL DEFAULT 0, amount_paid DECIMAL(15,2) NOT NULL DEFAULT 0, balance_due DECIMAL(15,2) NOT NULL DEFAULT 0, notes TEXT, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (client_id) REFERENCES clients(id), FOREIGN KEY (request_id) REFERENCES service_requests(id) ON DELETE SET NULL, FOREIGN KEY (quotation_id) REFERENCES quotations(id) ON DELETE SET NULL, FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS invoice_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, description VARCHAR(255) NOT NULL, quantity DECIMAL(12,2) NOT NULL DEFAULT 1, unit_price DECIMAL(15,2) NOT NULL DEFAULT 0, line_total DECIMAL(15,2) NOT NULL DEFAULT 0, FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, receipt_number VARCHAR(50) NOT NULL UNIQUE, payment_date DATE NOT NULL, amount DECIMAL(15,2) NOT NULL, method ENUM('CASH','BANK_TRANSFER','MPESA','CARD','CHEQUE','OTHER') NOT NULL DEFAULT 'BANK_TRANSFER', reference VARCHAR(120), notes TEXT, received_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (invoice_id) REFERENCES invoices(id), FOREIGN KEY (received_by) REFERENCES users(id) ON DELETE SET NULL);
